<script setup>
import {computed} from 'vue'
const props=defineProps({readings:{type:Array,default:()=>[]}})
const groups=computed(()=>['sensor','simulation'].map(source=>({source,label:source==='sensor'?'传感器来源':'模拟回放',items:props.readings.filter(r=>r.source===source&&Number.isFinite(Date.parse(r.timestamp))).sort((a,b)=>Date.parse(a.timestamp)-Date.parse(b.timestamp))})).filter(g=>g.items.length))
function chart(items,key){const p=items.filter(r=>r[key]!==null&&r[key]!==undefined&&Number.isFinite(Number(r[key])));if(!p.length)return null;const t0=Date.parse(p[0].timestamp),t1=Date.parse(p.at(-1).timestamp),ys=p.map(r=>Number(r[key]));let lo=Math.min(...ys),hi=Math.max(...ys);const pad=Math.max((hi-lo)*.12,key==='temperature'?1:2);lo-=pad;hi+=pad;const point=r=>({x:44+(Date.parse(r.timestamp)-t0)/Math.max(t1-t0,1)*632,y:154-(Number(r[key])-lo)/(hi-lo)*128,r});const points=p.map(point);let path='';points.forEach((v,i)=>{const previous=points[i-1];path+=`${!previous||Date.parse(v.r.timestamp)-Date.parse(previous.r.timestamp)>120000?'M':'L'}${v.x.toFixed(2)},${v.y.toFixed(2)} `});return {points,path,lo,hi,first:p[0].timestamp,last:p.at(-1).timestamp}}
const charts=computed(()=>groups.value.flatMap(g=>['temperature','humidity'].map(key=>({key,...g,data:chart(g.items,key),unit:key==='temperature'?'℃':'%RH',label:`${g.label} · ${key==='temperature'?'温度':'湿度'}`})).filter(g=>g.data)))
</script>
<template><section v-if="charts.length" class="card"><h2>同批次温湿度曲线</h2><p class="footnote">仅展示已保存的最近读数；模拟与传感器来源分开。超过两分钟的间隔断线显示，不将缺测推断为恢复；图上断线阈值不是后台业务规则。</p><article v-for="c in charts" :key="`${c.source}-${c.key}`" class="q3-trend"><h3>{{c.label}}（{{c.unit}}）</h3><svg viewBox="0 0 720 180" role="img" :aria-label="c.label"><line x1="44" y1="26" x2="44" y2="154" stroke="currentColor"/><line x1="44" y1="154" x2="676" y2="154" stroke="currentColor"/><text x="4" y="30">{{c.data.hi.toFixed(1)}}</text><text x="4" y="154">{{c.data.lo.toFixed(1)}}</text><path :d="c.data.path" fill="none" stroke="currentColor" stroke-width="2"/><circle v-for="(p,i) in c.data.points" :key="i" :cx="p.x" :cy="p.y" r="3" fill="currentColor"><title>{{p.r.timestamp}} · {{p.r[c.key]}} {{c.unit}}</title></circle></svg><p class="footnote">{{c.data.first}} — {{c.data.last}}</p></article></section></template>
<style scoped>.q3-trend{margin-top:20px;padding:16px;border:1px solid #e1e9e4;border-radius:10px}.q3-trend svg{width:100%;color:#27775b}.q3-trend text{font-size:11px;fill:#5b6e66}.q3-trend h3{margin:0}</style>
